import { StringColumn, GenericColumn, BooleanColumn, Table } from '../../db'

export const sys_ui_page = Table({
    name: 'sys_ui_page',
    extends: 'sys_metadata',
    schema: {
        category: StringColumn({
            mandatory: false,
            label: 'Category',
            read_only: false,
            active: true,
            default: 'general',
            maxLength: 40,
            dropdown: 'dropdown_with_none',
            choices: {
                cms: { label: 'Content Management', inactive: false, language: 'en' },
                catalog: { label: 'Service Catalog', inactive: false, language: 'en' },
                homepages: { label: 'Home Pages', inactive: false, language: 'en' },
                general: { label: 'General', inactive: false, language: 'en' },
                htmleditor: { label: 'HTML Editor', inactive: false, language: 'en' },
                kb: { label: 'Knowledge Base', inactive: false, language: 'en' },
            },
        }),
        client_script: GenericColumn({
            mandatory: false,
            label: 'Client script',
            read_only: false,
            active: true,
            column_type: 'script_plain',
        }),
        description: StringColumn({
            mandatory: false,
            label: 'Description',
            read_only: false,
            active: true,
            maxLength: 4000,
            dropdown: 'none',
        }),
        direct: BooleanColumn({ mandatory: false, label: 'Direct', read_only: false, active: true }),
        endpoint: GenericColumn({
            mandatory: false,
            label: 'Endpoint',
            read_only: true,
            active: true,
            column_type: 'url',
        }),
        html: GenericColumn({
            mandatory: false,
            label: 'HTML',
            read_only: false,
            active: true,
            default:
                '<?xml version="1.0" encoding="utf-8" ?>\r\n<j:jelly trim="false" xmlns:j="jelly:core" xmlns:g="glide" xmlns:j2="null" xmlns:g2="null">\r\n\r\n</j:jelly>',
            column_type: 'xml',
        }),
        name: StringColumn({
            mandatory: false,
            label: 'Name',
            read_only: false,
            active: true,
            maxLength: 250,
            dropdown: 'none',
        }),
        processing_script: GenericColumn({
            mandatory: false,
            label: 'Processing script',
            read_only: false,
            active: true,
            column_type: 'script_plain',
        }),
        sys_id: GenericColumn({
            mandatory: false,
            label: 'Sys ID',
            read_only: false,
            active: true,
            column_type: 'GUID',
        }),
    },
})
